with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_NO))) as HUB_POLICY_HK
        , HPR_DISCLAIMER11 as CLAUSE_TITLE
        , 'BJAZ_GRP_HLT_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_dtls') }}
    where (nullif(trim(POLICY_NO),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CLAUSE_TITLE end) as CLAUSE_TITLE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when CLAUSE_TITLE is not null
                     then md5(upper(coalesce(cast(CLAUSE_TITLE as varchar), '')))
                end as SAT_POLICY_CLAUSE_ATTACHED_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_CLAUSE_ATTACHED_HASHDIFF is not null
